#include "main.h"
#include "app.h"
#include <stdint.h>

// Handles generated by CubeMX in main.c
extern IWDG_HandleTypeDef hiwdg;
extern TIM_HandleTypeDef htim3;

// Tunable timings (in milliseconds)
#define QUALIFY_MS              5u    // inputs healthy this long before closing allowed
#define SWITCH_DEBOUNCE_MS      20u   // S501 must hold a level this long to register
#define HANDOVER_STABLE_MS      2u    // L-L must persist across 2 ticks (>= 1 ms real time)
#define PRECHARGE_TIMEOUT_MS    100u  // nominal ~16 ms for 2 mF; fault if exceeded
#define HANDOVER_OVERLAP_MS     5u    // CCEN and PREEN both on before PREEN drops
#define HEARTBEAT_MS            100u  // LED toggle while running
#define HEARTBEAT_FAULT_STEP_MS 1000u // LED toggle when faulted: (fault bit index + 1) x this

// Fast pin access functions (for single-cycle register operations)
static inline bool pin_high(GPIO_TypeDef *port, uint16_t pin) { return (port->IDR & pin) != 0u; }
static inline void pin_set (GPIO_TypeDef *port, uint16_t pin) { port->BSRR = pin; }
static inline void pin_clr (GPIO_TypeDef *port, uint16_t pin) { port->BRR  = pin; }

/*
   Comparator polarity (AMC23C14 datasheet, window-comparator mode)

     OUT1 (adjustable REF): LOW when the input is ABOVE its threshold
     OUT2 (fixed 300 mV)  : LOW when the input is ABOVE its threshold
     Loss of VDD1         : BOTH outputs LOW

   U301 input bus : OUT1 = INCMP1 (OV 65.8 V), OUT2 = INCMP2 (UV 48.6 V)
   U302 output bus: OUT1 = OUTCMP1 (~55.6 V),  OUT2 = OUTCMP2 (~45.2 V)

   Input bus healthy = INCMP1 high, INCMP2 low. A dead U301 supply reads
   as overvoltage, so the relay opens.

   An unpowered U302 (output below ~20 V at the start of precharge) also
   reads L-L, the same as "above 55.6 V". The handover therefore only
   triggers after u302_armed is set by a non-L-L reading during precharge.
*/
#define INPUT_NOT_OV()      ( pin_high(INCMP1_GPIO_Port,  INCMP1_Pin))
#define INPUT_NOT_UV()      (!pin_high(INCMP2_GPIO_Port,  INCMP2_Pin))
#define OUTPUT_ABOVE_55V()  (!pin_high(OUTCMP1_GPIO_Port, OUTCMP1_Pin))
#define OUTPUT_ABOVE_45V()  (!pin_high(OUTCMP2_GPIO_Port, OUTCMP2_Pin))

// TPSI open-drain outputs: FLT1/ALM1 active-low, PGOOD high = supply good
#define CC_SUPPLY_OK()      ( pin_high(CCPGOOD_GPIO_Port,  CCPGOOD_Pin))
#define PRE_SUPPLY_OK()     ( pin_high(PREPGOOD_GPIO_Port, PREPGOOD_Pin))
#define CC_NO_TRIP()        ( pin_high(CCFLT_GPIO_Port,    CCFLT_Pin))
#define CC_NO_ALARM()       ( pin_high(CCALM_GPIO_Port,    CCALM_Pin))

// S501 switches PF0 to GND against the internal pull-up: LOW = ON
#define SWITCH_RAW_ON()     (!pin_high(SWITCH_GPIO_Port, SWITCH_Pin))

// State
static volatile relay_state_t   state =         STATE_INIT;
static volatile uint32_t        faults =        0u;
static volatile uint32_t        warnings =      0u;
static volatile uint32_t        first_fault =   0u;     // first fault bit latched; sets the blink rate

static uint32_t  t_state_entry;     // tick when current state was entered
static uint32_t  t_healthy_since;   // tick when inputs last became healthy
static bool      was_healthy;
static uint32_t  t_heartbeat;

static bool      sw_on;             // debounced S501 level
static bool      sw_raw_last;       // last raw S501 reading
static uint32_t  t_sw_change;       // tick of the last raw S501 change
static bool      sw_armed;          // S501 has been seen OFF since reset

static bool      u302_armed;        // U302 has shown a non-L-L code this precharge
static uint32_t  t_ll_since;        // tick of the last non-L-L reading

// Relay control

// Open both paths immediately. Safe to call from any context.
static inline void relay_open_all(void)
{
    pin_clr(CCEN_GPIO_Port, CCEN_Pin);
    pin_clr(PREEN_GPIO_Port, PREEN_Pin);
}

static inline bool is_energised(relay_state_t s)
{
    return (s == STATE_PRECHARGE) || (s == STATE_HANDOVER) || (s == STATE_ON);
}

// Record a fault, remembering which one latched first.
static inline void latch_fault(uint32_t fault_bit)
{
    if (faults == 0u) {
        first_fault = fault_bit;
    }
    faults |= fault_bit;
}

// Called from ISRs: open first, then record.
static inline void trip(uint32_t fault_bit)
{
    relay_open_all();
    latch_fault(fault_bit);
}

// Fault blink: bit 0 -> 1 s, bit 1 -> 2 s, ... bit 6 -> 7 s per toggle.
static uint32_t fault_blink_ms(uint32_t fault_bit)
{
    uint32_t n = 1u;
    while (fault_bit > 1u) {
        fault_bit >>= 1;
        n++;
    }
    return n * HEARTBEAT_FAULT_STEP_MS;
}

/*
    Assert an enable pin and change state, but only if no fault is latched.
    ISRs are masked for a few cycles so an ISR cannot latch a fault between
    the check and the pin write.
*/
static bool energise(GPIO_TypeDef *port, uint16_t pin, relay_state_t next)
{
    bool ok;
    __disable_irq();
    ok = (faults == 0u);
    if (ok) {
        state = next;
        pin_set(port, pin);
    }
    __enable_irq();
    return ok;
}

static void enter_state(relay_state_t next)
{
    state = next;
    t_state_entry = HAL_GetTick();
}

// Input health
static bool inputs_healthy_now(void)
{
    return  INPUT_NOT_OV() && INPUT_NOT_UV() &&
            CC_SUPPLY_OK() && PRE_SUPPLY_OK() && CC_NO_TRIP();
}

// Debounced: healthy continuously for QUALIFY_MS. Call once per loop.
static bool inputs_qualified(uint32_t now)
{
    if (inputs_healthy_now()) {
        if (!was_healthy) {
            was_healthy = true;
            t_healthy_since = now;
        }
        return (now - t_healthy_since) >= QUALIFY_MS;
    }
    was_healthy = false;
    return false;
}

// S501: debounce the raw level, arm once OFF has been seen. Call once per loop.
static void switch_poll(uint32_t now)
{
    bool raw = SWITCH_RAW_ON();
    if (raw != sw_raw_last) {
        sw_raw_last = raw;
        t_sw_change = now;
    } else if ((now - t_sw_change) >= SWITCH_DEBOUNCE_MS) {
        sw_on = raw;
    }
    if (!sw_on) {
        sw_armed = true;
    }
}

// Public API
void app_init(void)
{
    // Stop the IWDG counting while halted at a breakpoint (debug only).
    __HAL_RCC_DBGMCU_CLK_ENABLE();
    __HAL_DBGMCU_FREEZE_IWDG();

    relay_open_all();
    pin_clr(SCOPE_GPIO_Port, SCOPE_Pin);
    pin_clr(HEARTBEAT_GPIO_Port, HEARTBEAT_Pin);

    uint32_t now   = HAL_GetTick();
    t_state_entry  = now;
    t_heartbeat    = now;
    state          = STATE_INIT;
    u302_armed     = false;

    // Start from the current level so a switch left ON after a reset is not
    // armed: it must be turned OFF then ON again to close the relay.
    sw_raw_last    = SWITCH_RAW_ON();
    sw_on          = sw_raw_last;
    t_sw_change    = now;
    sw_armed       = false;

    HAL_TIM_IC_Start_IT(&htim3, TIM_CHANNEL_4);     // OUTCMP2 edges
}

void app_loop(void)
{
    uint32_t now       = HAL_GetTick();
    bool     qualified = inputs_qualified(now);

    switch_poll(now);

    // ---- Any fault latched by an ISR forces the fault state ----
    if (faults != 0u && state != STATE_FAULT) {
        relay_open_all();
        enter_state(STATE_FAULT);
        pin_clr(HEARTBEAT_GPIO_Port, HEARTBEAT_Pin);    // start the fault blink from off
        t_heartbeat = now;
    }

    // ---- S501 OFF opens the relay from any energised state ----
    if (!sw_on && is_energised(state)) {
        relay_open_all();
        enter_state(STATE_INIT);            // re-qualify before next close
    }

    // ---- State machine ----
    uint32_t in_state = now - t_state_entry;

    switch (state) {
    case STATE_INIT:
        relay_open_all();
        if (qualified) {
            enter_state(STATE_OFF);
        }
        break;

    case STATE_OFF:
        relay_open_all();
        if (!qualified) {
            enter_state(STATE_INIT);
        } else if (sw_on && sw_armed) {
            u302_armed = false;             // must re-prove U302 is powered every close
            t_ll_since = now;
            if (energise(PREEN_GPIO_Port, PREEN_Pin, STATE_PRECHARGE)) {
                enter_state(STATE_PRECHARGE);
            }
        }
        break;

    case STATE_PRECHARGE: {
        bool ll = OUTPUT_ABOVE_55V() && OUTPUT_ABOVE_45V();   // code L-L
        if (!ll) {
            // Any other code proves U302 is powered and below its threshold.
            u302_armed = true;
            t_ll_since = now;
        } else if (u302_armed && (now - t_ll_since) >= HANDOVER_STABLE_MS) {
            if (energise(CCEN_GPIO_Port, CCEN_Pin, STATE_HANDOVER)) {
                enter_state(STATE_HANDOVER);
            }
        }
        if (state == STATE_PRECHARGE && in_state > PRECHARGE_TIMEOUT_MS) {
            // Also expected if the input bus is below ~55.6 V, or if the
            // output was still charged above 55.6 V when S501 was turned on.
            trip(FAULT_PRECHARGE_TIMEOUT);
        }
        break;
    }

    case STATE_HANDOVER:
        if (in_state >= HANDOVER_OVERLAP_MS) {
            pin_clr(PREEN_GPIO_Port, PREEN_Pin);
            enter_state(STATE_ON);
        }
        break;

    case STATE_ON:
        // Protection is interrupt-driven; nothing to poll here.
        break;

    case STATE_FAULT:
        relay_open_all();
        break;
    }

    // ---- Watchdog: refreshed only from the loop, every pass ----
    HAL_IWDG_Refresh(&hiwdg);

    // ---- Heartbeat LED: fast while running, slow fault code when faulted ----
    uint32_t hb = (state == STATE_FAULT) ? fault_blink_ms(first_fault) : HEARTBEAT_MS;
    if ((now - t_heartbeat) >= hb) {
        t_heartbeat = now;
        HAL_GPIO_TogglePin(HEARTBEAT_GPIO_Port, HEARTBEAT_Pin);
    }
}

relay_state_t app_get_state(void)    { return state; }
uint32_t      app_get_faults(void)   { return faults; }
uint32_t      app_get_warnings(void) { return warnings; }

/*
   Interrupt callbacks (override HAL weak definitions)
   Priority 0 (EXTI, TIM3) - keep them short, no HAL_Delay, no printing.
*/

void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    pin_set(SCOPE_GPIO_Port, SCOPE_Pin);            // latency marker

    relay_state_t s = state;
    bool live = is_energised(s);

    switch (GPIO_Pin) {
    case CCFLT_Pin:
        if (!CC_NO_TRIP()) {
            relay_open_all();                       // stop TPSI3103 auto-retry
            if (live) { latch_fault(FAULT_OVERCURRENT); }
        }
        break;

    case INCMP1_Pin:
        if (live && !INPUT_NOT_OV()) { trip(FAULT_INPUT_OV); }
        break;

    case INCMP2_Pin:
        if (live && !INPUT_NOT_UV()) { trip(FAULT_INPUT_UV); }
        break;

    case CCPGOOD_Pin:
        if (live && !CC_SUPPLY_OK()) { trip(FAULT_CC_SUPPLY); }
        break;

    case PREPGOOD_Pin:
        if (live && !PRE_SUPPLY_OK()) { trip(FAULT_PRE_SUPPLY); }
        break;

    case CCALM_Pin:
        if (!CC_NO_ALARM()) { warnings |= WARN_OC_ALARM; }
        break;

    case OUTCMP1_Pin:
        // Handover level is polled in the loop; no action on edges.
        break;

    default:
        break;
    }

    pin_clr(SCOPE_GPIO_Port, SCOPE_Pin);
}

// OUTCMP2 (PB1) arrives via TIM3 CH4 input capture, both edges.
void HAL_TIM_IC_CaptureCallback(TIM_HandleTypeDef *htim)
{
    if (htim->Instance != TIM3 || htim->Channel != HAL_TIM_ACTIVE_CHANNEL_4) {
        return;
    }
    pin_set(SCOPE_GPIO_Port, SCOPE_Pin);

    relay_state_t s = state;
    // OUTCMP2 going high after handover means the output fell below ~45.2 V.
    // Must be caught on this edge: below ~20 V U302 loses VDD1 and reads L-L.
    if ((s == STATE_HANDOVER || s == STATE_ON) && !OUTPUT_ABOVE_45V()) {
        trip(FAULT_OUTPUT_COLLAPSE);
    }

    pin_clr(SCOPE_GPIO_Port, SCOPE_Pin);
}
